/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  phases([[0,14],[14,40],[40,60],[60,80]]);
  var ng = 0;
  for (var i = 0; i < 5; i++) { v['gx'+i] = lin([[15 + i * 2.5, 0],[17 + i * 2.5, 1]]) * out; if (p >= 16 + i * 2.5) ng++; }
  for (var j = 0; j < 3; j++) { v['gy'+j] = lin([[28 + j * 2.5, 0],[30 + j * 2.5, 1]]) * out; if (p >= 29 + j * 2.5) ng++; }
  for (var k = 0; k < 6; k++) v['l'+k] = p >= 30 + k * 1.5 ? out : 0.25 * out;
  v.ng = ng;
  var mv = lin([[42,0],[46,1]]), fx = lin([[62,0],[68,1]]);
  v.ac = 'transform: translateX(' + (12 * mv).toFixed(1) + 'px);';
  v.mc = 'transform: translateX(' + (12 * fx).toFixed(1) + 'px);';
  v.wn = (p >= 46 && p < 64) ? out : 0; v.wx = 212;
  v.al = (p >= 46 && p < 66) ? 1 : 0; v.alc = v.al ? '#C0392B' : '#1E7F4F';
  v.fin = (p >= 72 && p < 97) ? out : 0;

  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
export default card;
